请对以下 case 进行三维加权评分。

=== case_id ===
Case-28-veggie-price-009

=== 用户原始指令 (query.txt) ===
比价卡点一下跳买菜app，能看到已比完的状态嘛

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "比价卡点一下跳买菜app，能看到已比完的状态嘛",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.example.maicai",
        "abilityName": "",
        "uri": "maicai://price-comparison/result"
      }
    }
  ],
  "dataModelSchema": {
    "comparison": {
      "title": {
        "type": "string",
        "description": "菜价比价卡片的服务对象标题。",
        "sampleValue": "菜价比价"
      },
      "statusText": {
        "type": "string",
        "description": "当前比价流程的完成状态展示文本。",
        "sampleValue": "已比完"
      },
      "summaryText": {
        "type": "string",
        "description": "已完成比价后的简短结果摘要。",
        "sampleValue": "3家已比 · 省¥6.8"
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "打开买菜应用查看比价结果的短动作文案。",
        "sampleValue": "打开买菜"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/checkmark_calendar_fill.svg",
      "description": "带对勾的确认图标，适合表达比价任务已经完成或结果已确认的状态。"
    }
  ]
}

